import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** End-of-card consequence uses the existing suspended resolution/checkpoint lifecycle. */
public final class TrainerEndTurnTest {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B,WATCH=new UUID(0,6500);
    static final String ATTACH="""
        {"type":"attach_energy","target":"SELECT_OWN_POKEMON","source":"DECK","amount":4,"minimum":0,
         "target_scope":"OWN_FIELD","basic_energy_only":true,"energy_type":"WATER"}
        """;
    static void check(boolean b,String s){GeneratedRuleBatch8Test.check(b,s);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static void atomic(ServerMatch m,Runnable r){var a=m.privateView(A);var b=m.privateView(B);var rng=m.randomTranscript();var ca=m.clientView(A);reject(r);check(a.equals(m.privateView(A))&&b.equals(m.privateView(B))&&ca.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Rejected action mutated game");}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return GeneratedRuleBatch13Test.hand(m,p,id);}
    static TrainerProfile trainer(String effects,boolean ends){return BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"SUPPORTER\",\"endsTurn\":"+ends+",\"effects\":["+effects+"]}").getAsJsonObject(),EffectRegistry.standard());}
    static class Config {
        TrainerProfile trainer=trainer(ATTACH,true);String id="trainer";CardDefinition definition;
        List<AbilityDefinition> own=List.of(),other=List.of();boolean later=true;int seed=0;
    }
    static ServerMatch game(){return game(new Config());}
    static ServerMatch game(Config c){
        var defs=new ArrayList<CardDefinition>();
        for(String id:List.of("basic","opponent","water","fire","special",c.id,"support")){
            boolean pokemon=Set.of("basic","opponent").contains(id),trainer=id.equals(c.id)||id.equals("support");
            defs.add(id.equals(c.id)&&c.definition!=null?c.definition:new CardDefinition(id,id,pokemon?CardCategory.POKEMON:trainer?CardCategory.TRAINER:CardCategory.ENERGY,trainer?TrainerCategory.SUPPORTER:TrainerCategory.NONE,"J",Set.of("international"),pokemon,Set.of("water","fire").contains(id),60,Map.of(),EffectSupport.SUPPORTED,null));
        }
        var q=GeneratedRuleBatch8Test.entry("me5-5_en_084").getAsJsonArray("attacks").get(0).getAsJsonObject().deepCopy();q.add("energyCost",new JsonObject());
        var attacks=List.of(GeneratedRuleBatch59Test.hit(EnergyType.COLORLESS,false,0),BundledCombatData.attack(q,EffectRegistry.standard()));
        var own=new PokemonProfile(500,0,null,null,0,null,0,1,attacks,c.own,EnergyType.WATER);
        var other=new PokemonProfile(500,0,null,null,0,null,0,1,attacks,c.other,EnergyType.WATER);
        var catalog=new CombatCatalog(Map.of("basic",own,"opponent",other),Map.of("water",EnergyType.WATER,"fire",EnergyType.FIRE),Map.of(c.id,c.trainer,"support",new TrainerProfile(TrainerCategory.SUPPORTER,new TrainerEffect(TrainerEffect.Opcode.DRAW,1,0))),Map.of("special",EnergyProfile.fixed(EnergyType.WATER,2)));
        for(int seed=c.seed;seed<c.seed+2000;seed++){
            var decks=new ArrayList<List<CardInstance>>();for(UUID owner:List.of(A,B)){var ids=new ArrayList<String>();for(String key:List.of("basic","water","fire","special",c.id,"support"))for(int i=0;i<Map.of("basic",8,"water",24,"fire",8,"special",8,c.id,4,"support",8).get(key);i++)ids.add(key);var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++){String id=ids.get(i);if(owner.equals(B)&&id.equals("basic"))id="opponent";cards.add(new CardInstance(new UUID(owner.getLeastSignificantBits(),i+1),owner,id));}decks.add(cards);}
            var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(x->m.cardDefinition(x.definitionId()).basicPokemon()).count()<2))continue;
            OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,20);m.drawCardsByEffect(A,B,20);if(c.later){m.endTurn(A);m.endTurn(B);}
            if(List.of(A,B).stream().allMatch(p->m.privateView(p).hand().stream().filter(x->x.definitionId().equals(c.id)).count()>=2&&m.privateView(p).hand().stream().anyMatch(x->x.definitionId().equals("support"))&&m.privateView(p).deck().stream().filter(x->x.definitionId().equals("water")).count()>=5))return m;
        }throw new AssertionError("No turn-ending Trainer fixture");
    }
    static CardInstance play(ServerMatch m,String id){var c=hand(m,A,id);m.playTrainer(A,c.instanceId(),null);return c;}
    static void select(ServerMatch m,int count){var p=m.effectCardPrompt(A);m.submitEffectCards(A,p.resolutionId(),p.step(),p.candidates().stream().limit(count).map(CardInstance::instanceId).toList());}
    static void target(ServerMatch m,UUID owner,UUID host){var p=m.effectAttachmentPrompt(A);m.chooseEffectAttachmentTarget(A,p.resolutionId(),p.step(),host);}
    static void finished(ServerMatch m,int turn){check(m.phase()==MatchPhase.TURN&&m.currentPlayer().equals(B)&&m.turnNumber()==turn+1&&!m.hasPendingEffectChoice()&&m.triggerOrderPrompt()==null,"Turn did not advance exactly once after complete card");}
    static AbilityDefinition cardWatcher(String effects){return BundledCombatData.ability(JsonParser.parseString("{\"id\":\"support-watch\",\"nameZh\":\"watch\",\"kind\":\"TRIGGERED\",\"effectSupport\":\"SUPPORTED\",\"eventPolicy\":{\"trigger\":\"ON_CARD_PLAYED\",\"player\":\"OPPONENT\",\"card\":\"SUPPORTER\",\"optional\":true,\"usage\":\"ONCE_PER_TURN\"},\"triggers\":[{\"trigger\":\"ON_CARD_PLAYED\",\"conditions\":[{\"type\":\"IS_ACTIVE\",\"target\":\"SELF\"}],\"effects\":["+effects+"]}]}").getAsJsonObject(),EffectRegistry.standard());}
    public static void main(String[] args){schema();simpleAndCompatibility();reactions();knockout();attempts();abilityCompatibility();concession();System.out.println("TrainerEndTurnTest passed: explicit validated consequence, complete suspended card before end, optional/mandatory attachment and card-play reactions, triggered choices/KO/prize/replacement/checkup, failed Trainer attempts, legacy compatibility and concession cleanup");}
    static void schema(){var t=trainer(ATTACH,true);check(t.endsTurn(),"Missing consequence");check(!new TrainerProfile(t.category(),t.effect(),t.effectProgram()).endsTurn()&&!new TrainerProfile(t.category(),t.effect(),t.effectProgram(),List.of()).endsTurn(),"Old constructors changed");for(String bad:List.of("\"true\"","1","null","[]","{}"))reject(()->BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"SUPPORTER\",\"endsTurn\":"+bad+",\"effects\":["+ATTACH+"]}").getAsJsonObject(),EffectRegistry.standard()));reject(()->BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"SUPPORTER\",\"endsTurn\":true,\"effect\":{\"opcode\":\"DRAW\",\"amount\":1}}").getAsJsonObject(),EffectRegistry.standard()));reject(()->new TrainerProfile(TrainerCategory.STADIUM,new TrainerEffect(TrainerEffect.Opcode.STADIUM_BASIC_RETREAT_REDUCTION,1,0),EffectProgram.EMPTY,List.of(),true));}
    static void simpleAndCompatibility(){for(boolean ends:List.of(false,true)){var c=new Config();c.trainer=trainer(ATTACH,ends);var m=game(c);m.endTurn(A);m.applySpecialConditionByEffect(B,A,SpecialCondition.POISONED);m.applySpecialConditionByEffect(B,A,SpecialCondition.PARALYZED);m.endTurn(B);int turn=m.turnNumber(),damage=m.activePokemonView(A).damage();var used=play(m,c.id);check(m.currentPlayer().equals(A)&&m.activePokemonView(A).damage()==damage,"Turn ended before private search");select(m,1);check(m.currentPlayer().equals(A),"Turn ended before host choice");target(m,A,bench(m,A));check(m.privateView(A).discard().contains(used),"Resolving Trainer not discarded");if(ends){finished(m,turn);check(m.activePokemonView(A).damage()==damage+10&&!m.activePokemonView(A).conditions().contains(SpecialCondition.PARALYZED),"Normal checkup omitted");}else check(m.currentPlayer().equals(A)&&m.activePokemonView(A).damage()==damage,"Old trainer acquired consequence");}}
    static void reactions(){String choice="{\"type\":\"choice\",\"options\":[{\"type\":\"draw\",\"amount\":1},{\"type\":\"draw\",\"amount\":2}]}";var c=new Config();c.own=List.of(EnergyTriggeredAbilityTest.ability("attach-watch","SELF",true,"ONCE_PER_TURN",choice));c.other=List.of(cardWatcher(choice));var m=game(c);int turn=m.turnNumber(),a=m.privateView(A).hand().size(),b=m.privateView(B).hand().size();var used=play(m,c.id);select(m,1);target(m,A,active(m,A));check(m.privateView(A).discard().contains(used)&&m.currentPlayer().equals(A)&&m.triggerOrderPrompt()!=null,"Card was not finished before its reactions");int decisions=0,choices=0;while(m.currentPlayer().equals(A)){atomic(m,()->m.endTurn(A));atomic(m,()->m.playTrainer(A,hand(m,A,"support").instanceId(),null));if(m.triggerOrderPrompt()!=null){var p=m.triggerOrderPrompt();if(p.optionalDecision()){m.decideTriggeredEffect(p.choosingPlayer(),p.id(),true);decisions++;}else m.chooseTriggeredEffect(p.choosingPlayer(),p.id(),p.entries().getFirst().id());}else if(m.hasPendingEffectChoice()){UUID owner=m.clientView(A).choicePlayer();var p=m.effectChoicePrompt(owner);m.chooseEffectOption(owner,p.resolutionId(),p.step(),0);choices++;}else throw new AssertionError("Turn end stranded");check(decisions+choices<10,"Reaction loop");}finished(m,turn);check(decisions==2&&choices==2&&m.privateView(A).hand().size()==a&&m.privateView(B).hand().size()==b+2,"Reaction ownership/count or next-turn draw wrong");}
    static void knockout(){var c=new Config();c.trainer=trainer("{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":50},{\"type\":\"choice\",\"options\":[{\"type\":\"draw\",\"amount\":1},{\"type\":\"draw\",\"amount\":2}]}",true);var m=game(c);int turn=m.turnNumber();play(m,c.id);check(m.currentPlayer().equals(A)&&m.hasPendingEffectChoice(),"KO ended card before choice");var p=m.effectChoicePrompt(A);m.chooseEffectOption(A,p.resolutionId(),p.step(),0);check(m.currentPlayer().equals(A)&&m.phase()!=MatchPhase.TURN,"Turn ended before KO settlement");StarterDeck100CombatTest.settleKnockouts(m);finished(m,turn);}
    static void attempts(){boolean heads=false,tails=false;for(int seed=0;seed<1000&&!(heads&&tails);seed++){var c=new Config();c.seed=seed;var m=game(c);m.endTurn(A);m.attack(B,"quaking-fist");int turn=m.turnNumber(),rng=m.randomTranscript().size();var used=play(m,c.id);boolean ok=GeneratedRuleBatch52Test.heads(m,rng);heads|=ok;tails|=!ok;if(ok){select(m,0);finished(m,turn);}else check(m.currentPlayer().equals(A)&&m.turnNumber()==turn&&m.privateView(A).discard().contains(used)&&!m.hasPendingEffectChoice()&&m.mayPlaySupporter(A),"Failed attempt spent quota or ended turn");}check(heads&&tails,"Both Trainer-attempt outcomes untested");}
    static void abilityCompatibility(){var ability=BundledCombatData.ability(JsonParser.parseString("{\"id\":\"end-ability\",\"nameZh\":\"end\",\"kind\":\"ACTIVATED_ONCE_PER_TURN\",\"effectSupport\":\"SUPPORTED\",\"endsTurn\":true,\"triggers\":[{\"trigger\":\"ONCE_PER_TURN\",\"effects\":[{\"type\":\"choice\",\"options\":[{\"type\":\"draw\",\"amount\":1},{\"type\":\"draw\",\"amount\":2}]}]}]}").getAsJsonObject(),EffectRegistry.standard());var c=new Config();c.own=List.of(ability);var m=game(c);int turn=m.turnNumber();m.useAbility(A,active(m,A),ability.id());check(m.currentPlayer().equals(A),"Ability ended before its choice");var p=m.effectChoicePrompt(A);m.chooseEffectOption(A,p.resolutionId(),p.step(),0);finished(m,turn);}
    static void concession(){var m=game();var used=play(m,"trainer");select(m,2);var p=m.effectAttachmentPrompt(A);var before=m.privateView(A);m.concede(A);check(m.phase()==MatchPhase.FINISHED&&!m.hasPendingEffectChoice()&&m.privateView(A).deck().equals(before.deck())&&m.privateView(A).discard().contains(used),"Concession committed attachments/left pending Trainer");atomic(m,()->m.chooseEffectAttachmentTarget(A,p.resolutionId(),p.step(),p.targets().getFirst()));}
}
